return new { playing=UnityEditor.EditorApplication.isPlaying, scenes=Enumerable.Range(0,UnityEngine.SceneManagement.SceneManager.sceneCount).Select(i=>new {path=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).path,roots=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).GetRootGameObjects().Select(o=>new {o.name,components=o.GetComponents<Component>().Select(c=>c==null?"missing":c.GetType().Name).ToArray()}).ToArray()}).ToArray(), background=UnityEngine.InputSystem.InputSystem.settings.backgroundBehavior.ToString(), uiCount=UnityEngine.Object.FindObjectsByType<Cheon.Tests.PlayerReactions.Test_PlayerReactionUI>(FindObjectsSortMode.None).Length};
